"""Argument parsing and selector expansion for the Wikisource downloader."""

import argparse
import json

from py_misc import get_wikisource_plan as wsplan
from pycmn import hebrew_verse_numerals as hvn
from pycmn import mam_bknas_and_std_bknas as mbkn_a_sbkn

__all__ = [
    "add_selector_opts",
    "validate_selector_args",
    "parse_args",
    "selected_book_plans",
    "affected_bkids",
]


def _positive_int(value):
    int_value = int(value)
    if int_value <= 0:
        raise argparse.ArgumentTypeError(value)
    return int_value


def add_selector_opts(parser):
    parser.add_argument("--book39")  # e.g. 1Samuel not I Samuel
    parser.add_argument("--chapter", type=_positive_int)  # e.g. 11
    parser.add_argument(
        "--book-chapters-json"
    )  # path to JSON list of book/chapter pairs
    parser.add_argument("--section6")  # e.g. SifEm


def _parser():
    out_parser = argparse.ArgumentParser()
    add_selector_opts(out_parser)
    return out_parser


def validate_selector_args(args, parser):
    assert hasattr(args, "book_chapters_json"), args
    assert hasattr(args, "book39"), args
    assert hasattr(args, "chapter"), args
    assert hasattr(args, "section6"), args
    if args.book_chapters_json:
        if args.book39 or args.chapter is not None or args.section6:
            parser.error(
                "--book-chapters-json is mutually exclusive with --book39,"
                " --chapter, and --section6"
            )
        return
    if args.chapter is not None:
        if args.book39 is None:
            parser.error("--chapter requires --book39")
        if args.section6 is not None:
            parser.error("--chapter cannot be combined with --section6")


def parse_args(argv=None):
    out_parser = _parser()
    args = out_parser.parse_args(argv)
    validate_selector_args(args, out_parser)
    return args


def _he_chnu_for_chapter(chapter_int):
    assert isinstance(chapter_int, int), chapter_int
    assert chapter_int > 0, chapter_int
    return hvn.INT_TO_STR_DIC[chapter_int]


def _filter_book_plan_to_requested_chapters(book_plan, requested_he_chnus):
    he_bn_sbn, he_chnus = book_plan
    filtered_he_chnus = [
        he_chnu for he_chnu in he_chnus if he_chnu in requested_he_chnus
    ]
    missing_he_chnus = set(requested_he_chnus) - set(filtered_he_chnus)
    assert not missing_he_chnus, (he_bn_sbn, sorted(missing_he_chnus))
    return he_bn_sbn, filtered_he_chnus


def _book_plan_for_book39(book39id):
    book_plans = list(wsplan.get_book_plans(book39id, None))
    assert len(book_plans) == 1, (book39id, len(book_plans))
    return book_plans[0]


def _book_plan_for_book39_chapter(book39id, chapter_int):
    book_plan = _book_plan_for_book39(book39id)
    he_chnu = _he_chnu_for_chapter(chapter_int)
    return _filter_book_plan_to_requested_chapters(book_plan, {he_chnu})


def _load_book_chapter_pairs(json_path):
    with open(json_path, "r", encoding="utf-8") as json_in_fp:
        raw_pairs = json.load(json_in_fp)
    assert isinstance(raw_pairs, list), json_path
    book_chapter_pairs = []
    for entry in raw_pairs:
        assert isinstance(entry, dict), entry
        book39id = entry["book39"]
        chapter = entry["chapter"]
        assert isinstance(book39id, str), entry
        assert isinstance(chapter, int) and not isinstance(chapter, bool), entry
        assert chapter > 0, entry
        book_chapter_pairs.append((book39id, chapter))
    return book_chapter_pairs


def _book_plans_for_json_path(json_path):
    requested_he_chnus_by_book39id = {}
    for book39id, chapter_int in _load_book_chapter_pairs(json_path):
        requested_he_chnus_by_book39id.setdefault(book39id, set()).add(
            _he_chnu_for_chapter(chapter_int)
        )
    return [
        _filter_book_plan_to_requested_chapters(
            _book_plan_for_book39(book39id), requested_he_chnus
        )
        for book39id, requested_he_chnus in requested_he_chnus_by_book39id.items()
    ]


def selected_book_plans(args):
    if args.book_chapters_json:
        return _book_plans_for_json_path(args.book_chapters_json)
    if args.chapter is not None:
        return [_book_plan_for_book39_chapter(args.book39, args.chapter)]
    return list(wsplan.get_book_plans(args.book39, args.section6))


def affected_bkids(book_plans):
    return [mbkn_a_sbkn.MAM_HBNP_TO_BK39ID[he_bn_sbn] for he_bn_sbn, _ in book_plans]
